INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Prokura immer an ein Arbeitsverhältnis gebunden?', 2, '[{"text": "Nein", "correct": true, "because": "Auch externe Personen können Prokura erhalten"}, {"text": "Ja", "correct": false, "because": "Kein Anstellungsvertrag nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Prokura?', 3, '[{"text": "Vertretung des Unternehmens", "correct": true, "because": "Ermöglicht Rechtsgeschäfte im Namen des Unternehmens"}, {"text": "Kostensenkung", "correct": false, "because": "Nicht primär"}, {"text": "Manuelle Verwaltung", "correct": false, "because": "Vertretung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte hat ein Prokurist typischerweise?', 5, '[{"text": "Abschluss von Verträgen", "correct": true, "because": "Gehört zu § 49 HGB"}, {"text": "Vertretung vor Gericht", "correct": true, "because": "Gerichtliche Geschäfte erlaubt"}, {"text": "Verkauf von Grundstücken", "correct": false, "because": "Nur mit Sonderermächtigung"}, {"text": "Insolvenzantrag stellen", "correct": false, "because": "Grundlagengeschäft"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Prokura wird ins Handelsregister eingetragen. b) Sie ist im Außenverhältnis einschränkbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nach § 50 HGB unwirksam"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Vergabe einer Prokura?', 4, '[{"text": "Handelsregistereintrag", "correct": false, "because": "Nach § 53 HGB erforderlich"}, {"text": "Geschäftsfähigkeit", "correct": false, "because": "Prokurist muss voll geschäftsfähig sein"}, {"text": "Musikwiedergabe", "correct": true, "because": "Irrelevant für Prokura"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Prokurist Grundstücke verkaufen darf?', 2, '[{"text": "Nein", "correct": true, "because": "Nur mit Sonderermächtigung (§ 49 Abs. 2 HGB)"}, {"text": "Ja", "correct": false, "because": "Nicht standardmäßig erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer darf eine Prokura erteilen?', 3, '[{"text": "Vollkaufmann", "correct": true, "because": "Nach § 48 HGB erforderlich"}, {"text": "Prokurist", "correct": false, "because": "Kann keine Prokura vergeben"}, {"text": "Minderjährige", "correct": false, "because": "Nicht geschäftsfähig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Prokura gibt es?', 5, '[{"text": "Einzelprokura", "correct": true, "because": "Alleinige Vertretung"}, {"text": "Gesamtprokura", "correct": true, "because": "Gemeinsame Vertretung"}, {"text": "Softwareprokura", "correct": false, "because": "Kein Rechtsbegriff"}, {"text": "Familienprokura", "correct": false, "because": "Nicht definiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Prokurist kann Verträge abschließen. b) Die Prokura erlischt automatisch bei Tod des Unternehmers. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch (§ 52 Abs. 3 HGB)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Vergabe einer Prokura?', 4, '[{"text": "Ausdrückliche Erklärung", "correct": false, "because": "Nach § 48 HGB nötig"}, {"text": "Handelsregistereintrag", "correct": false, "because": "Pflicht nach § 53 HGB"}, {"text": "Grafikdesign", "correct": true, "because": "Irrelevant für Prokura"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Prokurist eine Prokura weitergeben?', 2, '[{"text": "Nein", "correct": true, "because": "Nicht übertragbar (§ 52 Abs. 2 HGB)"}, {"text": "Ja", "correct": false, "because": "Nur Inhaber erteilt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einschränkungen gibt es für die Prokura?', 4, '[{"text": "Keine Grundstücke verkaufen", "correct": true, "because": "§ 49 Abs. 2 HGB"}, {"text": "Keine Insolvenzanträge", "correct": true, "because": "Grundlagengeschäft"}, {"text": "Keine Verträge", "correct": false, "because": "Erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Prokura nur für große Unternehmen ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Jeder Vollkaufmann kann erteilen"}, {"text": "Ja", "correct": false, "because": "Nicht auf Größe beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Vergabe einer Prokura?', 3, '[{"text": "Vertrauen", "correct": true, "because": "Prokurist hat weitreichende Befugnisse"}, {"text": "Minimale Verantwortung", "correct": false, "because": "Hohe Verantwortung nötig"}, {"text": "Manuelle Verwaltung", "correct": false, "because": "Rechtliche Vorgaben zählen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Prokura ist für natürliche Personen. b) Sie erlischt automatisch nach einem Jahr.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht zeitlich begrenzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Prokura?', 5, '[{"text": "Entlastung der Geschäftsführung", "correct": true, "because": "Delegiert Aufgaben"}, {"text": "Flexibilität im Geschäftsverkehr", "correct": true, "because": "Schnelle Entscheidungen"}, {"text": "Unbeschränkte Macht", "correct": false, "because": "Eingeschränkt durch HGB"}, {"text": "Kostensenkung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Prokura unwichtig?', 3, '[{"text": "Handelsregistereintrag", "correct": false, "because": "Pflicht nach § 53 HGB"}, {"text": "Geschäftsfähigkeit", "correct": false, "because": "Voraussetzung"}, {"text": "Bildschirmauflösung", "correct": true, "because": "Kein Rechtsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Prokura jederzeit widerrufbar ist?', 2, '[{"text": "Ja", "correct": true, "because": "Nach § 52 HGB möglich"}, {"text": "Nein", "correct": false, "because": "Widerruf immer erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Prokura für Minderjährige möglich?', 3, '[{"text": "Nein", "correct": true, "because": "Vollständige Geschäftsfähigkeit nötig"}, {"text": "Ja", "correct": false, "because": "Minderjährige ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zur Prokura?', 4, '[{"text": "Vertragsabschluss durch Abteilungsleiter", "correct": true, "because": "Typische Prokuristenaufgabe"}, {"text": "Musikwiedergabe", "correct": false, "because": "Kein Geschäftsbezug"}, {"text": "Netzwerkwartung", "correct": false, "because": "Technische Aufgabe"}]');
